{
  "story": "How does TCP establish a connection? Start with a closed client and listening server; assume no loss, reordering, or payload. Follow SYN, SYN-ACK, and ACK, comparing endpoint states. Each endpoint needs its own SYN acknowledged; the final ACK gives the server that evidence.",
  "aha": {
    "stateId": "both-established",
    "observation": "The final ACK confirms receipt of the server's SYN; both endpoints now have acknowledgments of their own SYNs."
  },
  "layout": {
    "preset": "protocol",
    "width": 640
  },
  "parts": [
    {
      "id": "handshake-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell with story and instructions above the experiment. Keep all five state labels visible.",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "handshake-trace",
      "kind": "progress",
      "presentation": "Integrate completed-state markers into the step rail. This represents discrete states, never elapsed time.",
      "bind": {
        "completedBefore": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "endpoint-picture",
      "kind": "fixed-picture",
      "presentation": "Use fixed Client and Server lanes with three ordered message rows. Links determine direction. Highlight active regions; muted routes are reference guides, not transmissions.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "endpoint-evidence",
      "kind": "value-readout",
      "presentation": "Pair Client and Server readouts on shared rows: connection state, then acknowledgment evidence. Put Status underneath. Wrap labels without shrinking text.",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor beside the named region without covering routes. Identify where the evidence changes; keep connection-state values exclusively in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.short",
        "reason": "state.why"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "presentation": "Parameter-control budget: zero; navigation is separate. Use Previous and Next, retaining disabled boundary labels. Default zero; bounds zero through four; increment one. Provide visible focus and keyboard operation. Every state persists until navigation, including the aha state. Reference captures show that state.",
      "items": "variant.states",
      "label": "Handshake state"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Restore the first state and all defaults. Provide visible focus and keyboard activation.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Client-initiated TCP handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "actors": [
              "Active opener"
            ]
          },
          {
            "id": "server",
            "label": "Server",
            "actors": [
              "Listening endpoint"
            ]
          },
          {
            "id": "syn",
            "label": "SYN",
            "values": [
              "Client's connection request"
            ]
          },
          {
            "id": "syn-ack",
            "label": "SYN-ACK",
            "values": [
              "Acknowledgment plus server's SYN"
            ]
          },
          {
            "id": "ack",
            "label": "ACK",
            "values": [
              "Acknowledgment of server's SYN"
            ]
          }
        ],
        "links": [
          {
            "from": "client",
            "to": "syn",
            "label": "Send"
          },
          {
            "from": "syn",
            "to": "server",
            "label": "Receive"
          },
          {
            "from": "server",
            "to": "syn-ack",
            "label": "Send"
          },
          {
            "from": "syn-ack",
            "to": "client",
            "label": "Receive"
          },
          {
            "from": "client",
            "to": "ack",
            "label": "Send"
          },
          {
            "from": "ack",
            "to": "server",
            "label": "Receive"
          }
        ],
        "states": [
          {
            "id": "ready",
            "label": "Ready",
            "short": "Client begins the exchange",
            "sentence": "The server is listening; the client has not sent SYN.",
            "why": "The client actively opens this connection. The server waits for an incoming request.",
            "active": [
              "client",
              "server"
            ],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "CLOSED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "LISTEN"
              },
              {
                "id": "client-evidence",
                "label": "Client's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "server-evidence",
                "label": "Server's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "No handshake messages have been sent."
              }
            ]
          },
          {
            "id": "syn-sent",
            "label": "SYN sent",
            "short": "SYN travels to Server",
            "sentence": "The client sends SYN; the server has not received it yet.",
            "why": "SYN starts the exchange, but sending a request does not establish that the peer received it.",
            "active": [
              "client",
              "syn"
            ],
            "calloutRegion": "syn",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "SYN-SENT"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "LISTEN"
              },
              {
                "id": "client-evidence",
                "label": "Client's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "server-evidence",
                "label": "Server's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "SYN is in transit from Client to Server."
              }
            ]
          },
          {
            "id": "syn-ack-sent",
            "label": "SYN-ACK sent",
            "short": "Server replies with SYN-ACK",
            "sentence": "The server receives SYN and sends SYN-ACK; the client has not received the reply yet.",
            "why": "SYN-ACK acknowledges the client's SYN and introduces the server's own SYN. The server still needs acknowledgment of its SYN.",
            "active": [
              "server",
              "syn-ack"
            ],
            "calloutRegion": "syn-ack",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "SYN-SENT"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "client-evidence",
                "label": "Client's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "server-evidence",
                "label": "Server's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "SYN-ACK is in transit from Server to Client."
              }
            ]
          },
          {
            "id": "ack-sent",
            "label": "ACK sent",
            "short": "Client sends the final ACK",
            "sentence": "The client receives SYN-ACK and sends ACK; the server has not received that ACK yet.",
            "why": "The client now has acknowledgment of its own SYN. Compare the endpoints: the server still lacks the corresponding evidence.",
            "active": [
              "client",
              "ack"
            ],
            "calloutRegion": "ack",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "client-evidence",
                "label": "Client's own SYN acknowledgment",
                "value": "Received"
              },
              {
                "id": "server-evidence",
                "label": "Server's own SYN acknowledgment",
                "value": "Not received"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "ACK is in transit; only Client has finished establishing the connection."
              }
            ]
          },
          {
            "id": "both-established",
            "label": "ACK received",
            "short": "Server receives the missing evidence",
            "sentence": "The server receives the final ACK; both endpoints have finished establishing the connection.",
            "why": "The final ACK acknowledges the server's SYN. Each endpoint has now received acknowledgment of its own SYN.",
            "active": [
              "client",
              "server",
              "ack"
            ],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "ESTABLISHED"
              },
              {
                "id": "client-evidence",
                "label": "Client's own SYN acknowledgment",
                "value": "Received"
              },
              {
                "id": "server-evidence",
                "label": "Server's own SYN acknowledgment",
                "value": "Received"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Both endpoints have the acknowledgment needed to establish the connection."
              }
            ]
          }
        ]
      }
    ]
  }
}
